INSERT INTO "patologia" ("id", "nombre", "descripcion") VALUES
(1, 'Diabetes Mellitus tipo 2', 'Enfermedad metabólica crónica caracterizada por hiperglicemia persistente debido a resistencia a la insulina y déficit progresivo de secreción insulínica. Requiere control periódico de hemoglobina glicosilada y glicemia en ayunas, junto a educación en autocuidado y pesquisa de complicaciones micro y macrovasculares.'),
(2, 'Hipertensión Arterial', 'Elevación sostenida de la presión arterial sobre 140/90 mmHg en población general. Principal factor de riesgo cardiovascular modificable en Chile. El manejo incluye tratamiento farmacológico, restricción de sodio y monitoreo periódico de presión arterial y daño de órgano blanco.'),
(3, 'Enfermedad Pulmonar Obstructiva Crónica', 'Limitación crónica y poco reversible del flujo aéreo, habitualmente asociada a tabaquismo o exposición a biomasa. Se evalúa mediante espirometría con medición de VEF1 y saturación de oxígeno. Las exacerbaciones son la principal causa de hospitalización.'),
(4, 'Insuficiencia Cardíaca', 'Síndrome clínico en que el corazón es incapaz de mantener un gasto cardíaco adecuado para la demanda metabólica. Se monitorea mediante fracción de eyección, péptido natriurético y control estricto de peso y balance hídrico.'),
(5, 'Enfermedad Renal Crónica', 'Deterioro progresivo e irreversible de la función renal por al menos tres meses, evaluado mediante velocidad de filtración glomerular y creatinina plasmática. Frecuentemente secundaria a diabetes e hipertensión de larga data.'),
(6, 'Dislipidemia', 'Alteración de los niveles plasmáticos de lípidos, principalmente elevación de colesterol LDL y triglicéridos. Contribuye directamente al desarrollo de ateroesclerosis y eventos cardiovasculares. Se maneja con estatinas y cambios en el estilo de vida.'),
(7, 'Asma Bronquial', 'Enfermedad inflamatoria crónica de la vía aérea con obstrucción reversible e hiperreactividad bronquial. Cursa con episodios de disnea, sibilancias y tos, habitualmente desencadenados por alérgenos, infecciones virales o ejercicio.'),
(8, 'Obesidad', 'Acumulación excesiva de tejido adiposo con índice de masa corporal igual o superior a 30 kg/m². Actúa como factor agravante de diabetes, hipertensión y patología osteoarticular. El manejo es multidisciplinario e incluye nutrición y actividad física supervisada.');
